import { clamp01, isoOrNull } from '../core/contracts.js';
function feature(subjectId,featureKey,value,source){if(!subjectId||!source?.sourceId||!isoOrNull(source.observedAt)||!Number.isFinite(value))return null;return{subjectId:String(subjectId),featureKey,value:clamp01(value),sourceId:String(source.sourceId),evidenceKind:source.evidenceKind||'OBSERVED',observedAt:isoOrNull(source.observedAt),validAt:isoOrNull(source.validAt)||isoOrNull(source.observedAt),confidence:clamp01(source.confidence??1)};}
export const mapKtoSignalToFeature=(row={})=>feature(row.placeId,row.metric,row.normalizedValue,{sourceId:row.sourceId||'KTO',evidenceKind:row.evidenceKind||'OBSERVED',observedAt:row.observedAt,validAt:row.validAt,confidence:row.confidence});
export const mapKmaWeatherToFeature=(row={})=>feature(row.placeId,'weather',row.suitability,{sourceId:row.sourceId||'KMA',evidenceKind:row.evidenceKind||'OFFICIAL_FORECAST',observedAt:row.issuedAt||row.observedAt,validAt:row.validAt,confidence:row.confidence});
export function mapAirKoreaToPollution(row={}){if(!row.stationId||!row.sourceId||!isoOrNull(row.observedAt)||!row.pollutant)return null;return{sourceId:row.sourceId,externalId:row.stationId,evidenceKind:'OBSERVED',domain:'AIR',pollutant:row.pollutant,observedAt:isoOrNull(row.observedAt),lat:Number.isFinite(row.lat)?row.lat:null,lon:Number.isFinite(row.lon)?row.lon:null,confidence:clamp01(row.confidence??1),payload:{value:row.value,unit:row.unit}};}
export function mapFirmsToFire(row={}){if(!row.hotspotId||!row.sourceId||!isoOrNull(row.observedAt))return null;return{sourceId:row.sourceId,externalId:row.hotspotId,evidenceKind:'DETECTED',domain:'FIRE',pollutant:null,observedAt:isoOrNull(row.observedAt),lat:Number.isFinite(row.lat)?row.lat:null,lon:Number.isFinite(row.lon)?row.lon:null,confidence:clamp01(row.confidence??1),payload:{frp:row.frp??null}};}
